    emit SwapExactPTForSY(address(market), exactPTIn, swapData, minSY);
}

function burnLP(IPMarket market, uint256 amount) external onlyManager nonReentrant {
    IERC20(address(market)).safeTransfer(address(market), amount);
    market.burn(address(this), address(market), amount);
    market.skim();
    emit BurnLP(address(market), amount);
}

function withdraw(uint256 amount, Id id, bool sOrC) external onlyManager nonReentrant {
    MarketParams memory params = morphoBlue.idToMarketParams(id);
    if (sOrC) {
        morphoBlue.withdraw(params, amount, 0, address(this), address(this));
    } else {
        morphoBlue.withdrawCollateral(params, amount, address(this), address(this));
    }
    Position memory p = morphoBlue.position(id, address(this));
    if (p.collateral == 0 && p.supplyShares == 0) {
        registry.updateHoldingPosition(
            vaultId, registry.calculatePositionId(address(this), MORPHO_POSITION_ID, abi.encode(id)), "", "", true
        );
    }
    _updateTokenInRegistry(params.collateralToken);
    emit Withdraw(amount, id, sOrC);
}

function _getHealthFactor(IFraxPair _fraxlendPair, uint256 _exchangeRate) internal view virtual returns (uint256) {
    // calculate the borrowShares
    uint256 borrowerShares = _fraxlendPair.userBorrowShares(address(this));
    uint256 _borrowerAmount = _fraxlendPair.toBorrowAmount(borrowerShares, true);
    if (_borrowerAmount == 0) return type(uint256).max;
    uint256 _collateralAmount = _fraxlendPair.userCollateralBalance(address(this));
    if (_collateralAmount == 0) return 0;
    (uint256 LTV_PRECISION,,,, uint256 EXCHANGE_PRECISION,,,) = _fraxlendPair.getConstants();
    uint256 currentPositionLTV =
        (((_borrowerAmount * _exchangeRate) * LTV_PRECISION) / EXCHANGE_PRECISION) / _collateralAmount;

    // get maxLTV from fraxlendPair
    uint256 fraxlendPairMaxLTV = _fraxlendPair.maxLTV();
    if (currentPositionLTV == 0) return type(uint256).max; // loan is small

    // // convert LTVs to HF
    uint256 currentHF = (fraxlendPairMaxLTV * 1e18) / currentPositionLTV;

    // // compare HF to current HF.
    return currentHF;
}

