    if (amount == 0) {
        revert NoyaAccounting_INVALID_AMOUNT();
    }

    baseToken.safeTransferFrom(msg.sender, address(this), amount);

    if (amount > depositLimitPerTransaction) {
        revert NoyaAccounting_DepositLimitPerTransactionExceeded();
