modifier onlyExistingRoute(uint256 _routeId) {
    if (routes[_routeId].route == address(0) && !routes[_routeId].isEnabled) revert RouteNotFound();
    _;
}

modifier onlyVaultMaintainer(uint256 _vaultId) {
    if (msg.sender != vaults[_vaultId].maintainer || hasRole(EMERGENCY_ROLE, msg.sender) == false) {
        revert UnauthorizedAccess();
    }
    _;
}

function executeBridge(BridgeRequest calldata _bridgeRequest)
    external
    payable
    onlyEligibleUser
    onlyExistingRoute(_bridgeRequest.routeId)
    nonReentrant
{
    RouteData memory bridgeImplInfo = routes[_bridgeRequest.routeId];

    if (!bridgeImplInfo.isBridge) revert RouteNotAllowedForThisAction();

    ISwapAndBridgeImplementation(bridgeImplInfo.route).performBridgeAction(msg.sender, _bridgeRequest);

    emit BridgeExecutionCompleted(_bridgeRequest);
}

function performBridgeAction(address caller, BridgeRequest calldata _request)
    external
    payable
    override
    onlyHandler
{
    verifyBridgeData(_request);
    _forward(IERC20(_request.inputToken), _request.from, _request.amount, caller, _request.data, _request.routeId);
    emit Bridged(_request.from, _request.inputToken, _request.amount, _request.data);
}

function _forward(IERC20 token, address from, uint256 amount, address caller, bytes calldata data, uint256 routeId)
    internal
    virtual
    nonReentrant
{
    if (!_isNative(token)) {
        ITokenTransferCallBack(from).sendTokensToTrustedAddress(address(token), amount, caller, abi.encode(routeId));

        _setAllowance(token, lifi, amount);
    }

    (bool success, bytes memory err) = lifi.call{ value: msg.value }(data);

    if (!success) {
        revert FailedToForward(err);
    }

    emit Forwarded(lifi, address(token), amount, data);
}

