function execute(
    address destination,
    bytes calldata data,
    uint256 gasLimit,
    address executor,
    bytes32[] memory sigR,
    bytes32[] memory sigS,
    uint8[] memory sigV,
    uint256 deadline
) public {
    require(isOwner[msg.sender], "Not an owner");
    require(sigR.length == threshold, "Not enough signatures");
    require(sigR.length == sigS.length && sigR.length == sigV.length, "Lengths do not match");
    require(executor == msg.sender, "Invalid executor");
    require(block.timestamp <= deadline, "Transaction expired");
    {
        bytes32 txInputHash =
            keccak256(abi.encode(TXTYPE_HASH, nonce, destination, data, gasLimit, executor, deadline));
        bytes32 totalHash = keccak256(abi.encodePacked("\x19\x01", _domainSeparatorV4(), txInputHash));
        address lastAdd = address(0);
        for (uint256 i = 0; i < threshold;) {
            address recovered = ECDSA.recover(totalHash, sigV[i], sigR[i], sigS[i]);
            require(recovered > lastAdd && isOwner[recovered]);
            lastAdd = recovered;
            unchecked {
                ++i;
            }
        }

        nonce++;
    }
    emit Execute(destination, data, gasLimit, executor, deadline);
    (bool success,) = destination.call{ gas: gasLimit }(data);
    require(success, "Transaction execution reverted.");
}

function calculateDepositShares(uint256 maxIterations) public onlyManager nonReentrant whenNotPaused {
    uint256 middleTemp = depositQueue.middle;
    uint64 i = 0;

    uint256 oldestUpdateTime = TVLHelper.getLatestUpdateTime(vaultId, registry);

    while (
        depositQueue.last > middleTemp && depositQueue.queue[middleTemp].recordTime <= oldestUpdateTime
            && i < maxIterations
    ) {
        i += 1;
        DepositRequest storage data = depositQueue.queue[middleTemp];

        uint256 shares = previewDeposit(data.amount);
        data.shares = shares;
        data.calculationTime = block.timestamp;
        emit CalculateDeposit(
            middleTemp, data.receiver, block.timestamp, shares, data.amount, shares * 1e18 / data.amount
        );

        middleTemp += 1;
    }

    depositQueue.middle = middleTemp;
}

function updateHoldingPostionWithTime(
    uint256 vaultId,
    bytes32 _positionId,
    bytes calldata _data,
    bytes calldata additionalData,
    bool removePosition,
    uint256 positionTimestamp
) external vaultExists(vaultId) {
    uint256 positionIndex = updateHoldingPosition(vaultId, _positionId, _data, additionalData, removePosition);
    if (positionIndex != type(uint256).max) {
        vaults[vaultId].holdingPositions[positionIndex].positionTimestamp = positionTimestamp;
    }
}

function updateHoldingPosition(
    Vault storage vault,
    uint256 vaultId,
    bytes32 _positionId,
    bytes calldata d,
    bytes calldata AD,
    uint256 index,
    bytes32 holdingPositionId
) internal returns (uint256) {
    emit HoldingPositionUpdated(vaultId, _positionId, d, AD, false, index);

    if (index == 0) {
        if (!isPositionTrustedForConnector(vaultId, _positionId, msg.sender)) {
            revert InvalidPosition(_positionId);
        }
        if (vault.holdingPositions.length >= maxNumHoldingPositions) {
            revert TooManyPositions();
        }
        vault.isPositionUsed[holdingPositionId] = vault.holdingPositions.length;
        vault.holdingPositions.push(
            HoldingPI(
                vaults[vaultId].trustedPositionsBP[_positionId].calculatorConnector,
                msg.sender,
                _positionId,
                d,
                AD,
                type(uint256).max
            )
        );
        return vault.holdingPositions.length - 1;
    }
    vault.holdingPositions[index].additionalData = AD;
    return index;
}

