function unwrap(
    uint256 amount,
    address recipient
) external lock onlyAlchemist returns (uint256) {
    // Transfer the tokens from the message sender.
    SafeERC20.safeTransferFrom(token, msg.sender, address(this), amount);

    uint256 balanceBeforeUnderlying = IERC20(underlyingToken).balanceOf(address(this));
    uint256 balanceBeforeYieldToken = IERC20(token).balanceOf(address(this));

    // Vesper withdraw does not accept a recipient argument and does not return withdrawn amount
    IVesperPool(token).withdraw(amount);

    uint256 balanceAfterUnderlying = IERC20(underlyingToken).balanceOf(address(this));
    uint256 balanceAfterYieldToken = IERC20(token).balanceOf(address(this));

    uint256 withdrawn = balanceAfterUnderlying - balanceBeforeUnderlying;

    if (balanceBeforeYieldToken - balanceAfterYieldToken != amount) {
        revert IllegalState("Not all shares were burned");
    }

    // We must transfer to recipient after and use IERC20.balanceOf() for amount
    SafeERC20.safeTransfer(underlyingToken, recipient, withdrawn);

    return withdrawn;
}

function wrap(
    uint256 amount,
    address recipient
) external onlyAlchemist returns (uint256) {
    // Transfer the underlying tokens from the message sender.
    SafeERC20.safeTransferFrom(underlyingToken, msg.sender, address(this), amount);
    SafeERC20.safeApprove(underlyingToken, token, amount);

    uint256 balanceBefore = IERC20(token).balanceOf(address(this));

    // Vesper deposit does not accept a recipient argument and does not return mint amount
    IVesperPool(token).deposit(amount);

    uint256 balanceAfter = IERC20(token).balanceOf(address(this));

    uint256 minted = balanceAfter - balanceBefore;

    // We must transfer to recipient after and use IERC20.balanceOf() for amount
    SafeERC20.safeTransfer(token, recipient, minted);

    return minted;
}

function unwrap(
    uint256 amount,
    address recipient
) external lock onlyAlchemist returns (uint256) {
    // Transfer the rETH from the message sender.
    SafeERC20.safeTransferFrom(token, msg.sender, address(this), amount);

    // Burn the rETH to receive ETH.
    uint256 startingEthBalance = address(this).balance;
    IRETH(token).burn(amount);
    uint256 receivedEth = address(this).balance - startingEthBalance;

    // Wrap the ETH that we received from the burn.
    IWETH9(underlyingToken).deposit{value: receivedEth}();

    // Transfer the tokens to the recipient.
    SafeERC20.safeTransfer(underlyingToken, recipient, receivedEth);

    return receivedEth;
}

function unwrap(
    uint256 amount,
    address recipient
) external lock onlyAlchemist returns (uint256) {
    // Transfer the tokens from the message sender.
    SafeERC20.safeTransferFrom(token, msg.sender, address(this), amount);

    // Unwrap the wstETH into stETH.
    uint256 startingStEthBalance = IStETH(parentToken).balanceOf(address(this));
    IWstETH(token).unwrap(amount);
    uint256 endingStEthBalance = IStETH(parentToken).balanceOf(address(this));

    // Approve the curve pool to transfer the tokens.
    uint256 unwrappedStEth = endingStEthBalance - startingStEthBalance;
    SafeERC20.safeApprove(parentToken, curvePool, unwrappedStEth);

    // Exchange the stETH for ETH. We do not check the curve pool because it is an immutable
    // contract and we expect that its output is reliable.
    uint256 received = IStableSwap2Pool(curvePool).exchange(
        int128(uint128(stEthPoolIndex)), // Why are we here, just to suffer?
        int128(uint128(ethPoolIndex)),   //                       (╥﹏╥)
        unwrappedStEth,
        0                                // <- Slippage is handled upstream
    );

    // Wrap the ETH that we received from the exchange.
    IWETH9(underlyingToken).deposit{value: received}();

    // Transfer the tokens to the recipient.
    SafeERC20.safeTransfer(underlyingToken, recipient, received);

    return received;
}

function wrap(
    uint256 amount,
    address recipient
) external lock onlyAlchemist returns (uint256) {
    // Transfer the tokens from the message sender.
    SafeERC20.safeTransferFrom(underlyingToken, msg.sender, address(this), amount);

    // Unwrap the WETH into ETH.
    IWETH9(underlyingToken).withdraw(amount);

    // Wrap the ETH into stETH.
    uint256 startingStEthBalance = IERC20(token).balanceOf(address(this));

    IStETH(parentToken).submit{value: amount}(referral);

    uint256 mintedStEth = IERC20(parentToken).balanceOf(address(this)) - startingStEthBalance;

    // Wrap the stETH into wstETH.
    SafeERC20.safeApprove(parentToken, address(token), mintedStEth);
    uint256 mintedWstEth = IWstETH(token).wrap(mintedStEth);

    // Transfer the minted wstETH to the recipient.
    SafeERC20.safeTransfer(token, recipient, mintedWstEth);

    return mintedWstEth;
}

function unwrap(
    uint256 amount,
    address recipient
) external lock onlyAlchemist returns (uint256) {
    SafeERC20.safeTransferFrom(token, msg.sender, address(this), amount);

    uint256 startingBalance = IERC20(underlyingToken).balanceOf(address(this));

    uint256 error;
    if ((error = ICERC20(token).redeem(amount)) != NO_ERROR) {
        revert FuseError(error);
    }

    uint256 endingBalance = IERC20(underlyingToken).balanceOf(address(this));
    uint256 redeemedAmount = endingBalance - startingBalance;

    SafeERC20.safeTransfer(underlyingToken, recipient, redeemedAmount);

    return redeemedAmount;
}

function wrap(
    uint256 amount,
    address recipient
) external onlyAlchemist returns (uint256) {
    SafeERC20.safeTransferFrom(underlyingToken, msg.sender, address(this), amount);
    SafeERC20.safeApprove(underlyingToken, token, amount);

    uint256 startingBalance = IERC20(token).balanceOf(address(this));

    uint256 error;
    if ((error = ICERC20(token).mint(amount)) != NO_ERROR) {
        revert FuseError(error);
    }

    uint256 endingBalance = IERC20(token).balanceOf(address(this));
    uint256 mintedAmount = endingBalance - startingBalance;

    SafeERC20.safeTransfer(token, recipient, mintedAmount);

    return mintedAmount;
}

function unwrap(uint256 amount, address recipient) external override returns (uint256) {
    TokenUtils.safeTransferFrom(token, msg.sender, address(this), amount);

    uint256 balanceBefore = TokenUtils.safeBalanceOf(token, address(this));

    uint256 amountWithdrawn = IYearnVaultV2(token).withdraw(amount, recipient, MAXIMUM_SLIPPAGE);

    uint256 balanceAfter = TokenUtils.safeBalanceOf(token, address(this));

    // If the Yearn vault did not burn all of the shares then revert. This is critical in mathematical operations
    // performed by the system because the system always expects that all of the tokens were unwrapped. In Yearn,
    // this sometimes does not happen in cases where strategies cannot withdraw all of the requested tokens (an
    // example strategy where this can occur is with Compound and AAVE where funds may not be accessible because
    // they were lent out).
    if (balanceBefore - balanceAfter != amount) {
        revert IllegalState();
    }

    return amountWithdrawn;
}

function wrap(uint256 amount, address recipient) external override returns (uint256) {
    TokenUtils.safeTransferFrom(underlyingToken, msg.sender, address(this), amount);
    TokenUtils.safeApprove(underlyingToken, token, amount);

    return IYearnVaultV2(token).deposit(amount, recipient);
}

function deposit(uint256 amount, address owner) external override nonReentrant {
  _onlyWhitelisted();
  _updateAccount(
    UpdateAccountParams({
      owner: owner,
      unexchangedDelta: SafeCast.toInt256(amount),
      exchangedDelta: 0
    })
  );
  TokenUtils.safeTransferFrom(syntheticToken, msg.sender, address(this), amount);
  emit Deposit(msg.sender, owner, amount);
}

function repay(address underlyingToken, uint256 amount, address recipient) external override lock returns (uint256) {
    _onlyWhitelisted();

    _checkArgument(amount > 0);
    _checkArgument(recipient != address(0));

    _checkSupportedUnderlyingToken(underlyingToken);
    _checkUnderlyingTokenEnabled(underlyingToken);

    // Distribute unlocked credit to depositors.
    _distributeUnlockedCreditDeposited(recipient);

    // Update the recipient's account and decrease the amount of debt incurred.
    _poke(recipient);

    // Check that the debt is greater than zero.
    //
    // It is possible that the amount of debt which is repayable is equal to or less than zero after realizing the
    // credit that was earned since the last update. We do not want to perform a noop so we need to check that the
    // amount of debt to repay is greater than zero.
    int256 debt;
    _checkState((debt = _accounts[recipient].debt) > 0);

    // Determine the maximum amount of underlying tokens that can be repaid.
    //
    // It is implied that this value is greater than zero because `debt` is greater than zero so a noop is not possible
    // beyond this point. Casting the debt to an unsigned integer is also safe because `debt` is greater than zero.
    uint256 maximumAmount = _normalizeDebtTokensToUnderlying(underlyingToken, uint256(debt));

    // Limit the number of underlying tokens to repay up to the maximum allowed.
    uint256 actualAmount = amount > maximumAmount ? maximumAmount : amount;

    Limiters.LinearGrowthLimiter storage limiter = _repayLimiters[underlyingToken];

    // Check to make sure that the underlying token repay limit has not been breached.
    uint256 currentRepayLimit = limiter.get();
    if (actualAmount > currentRepayLimit) {
      revert RepayLimitExceeded(underlyingToken, actualAmount, currentRepayLimit);
    }

    uint256 credit = _normalizeUnderlyingTokensToDebt(underlyingToken, actualAmount);

    // Update the recipient's debt.
    _updateDebt(recipient, -SafeCast.toInt256(credit));

    // Decrease the amount of the underlying token which is globally available to be repaid.
    limiter.decrease(actualAmount);

    // Transfer the repaid tokens to the transmuter.
    TokenUtils.safeTransferFrom(underlyingToken, msg.sender, transmuter, actualAmount);

    // Inform the transmuter that it has received tokens.
    IERC20TokenReceiver(transmuter).onERC20Received(underlyingToken, actualAmount);

    emit Repay(msg.sender, underlyingToken, actualAmount, recipient);

    return actualAmount;
}

function _wrap(
    address yieldToken,
    uint256 amount,
    uint256 minimumAmountOut
) internal returns (uint256) {
    YieldTokenParams storage yieldTokenParams = _yieldTokens[yieldToken];

    ITokenAdapter adapter = ITokenAdapter(yieldTokenParams.adapter);
    address underlyingToken = yieldTokenParams.underlyingToken;

    TokenUtils.safeTransferFrom(underlyingToken, msg.sender, address(this), amount);
    uint256 wrappedShares = adapter.wrap(amount, address(this));
    if (wrappedShares < minimumAmountOut) {
        revert SlippageExceeded(wrappedShares, minimumAmountOut);
    }

    return wrappedShares;
}

function deposit(
    address yieldToken,
    uint256 amount,
    address recipient
) external override lock returns (uint256) {
    _onlyWhitelisted();
    _checkArgument(recipient != address(0));
    _checkSupportedYieldToken(yieldToken);

    // Deposit the yield tokens to the recipient.
    uint256 shares = _deposit(yieldToken, amount, recipient);

    // Transfer tokens from the message sender now that the internal storage updates have been committed.
    TokenUtils.safeTransferFrom(yieldToken, msg.sender, address(this), amount);

    return shares;
}

